projects/index.content:
Active Projects
TABLE 
    status as &quot;Status&quot;, 
    tech as &quot;Technology&quot;,
    description as &quot;Description&quot;
FROM &quot;projects&quot;
WHERE status = &quot;active&quot; AND file.name != &quot;index&quot;
SORT date DESC
Completed Projects
TABLE 
    status as &quot;Status&quot;, 
    tech as &quot;Technology&quot;,
    date as &quot;Completion Date&quot;,
    description as &quot;Description&quot;
FROM &quot;projects&quot;
WHERE status = &quot;completed&quot; AND file.name != &quot;index&quot;
SORT date DESC
